    await sleep(100);
    if (stopping) {
      db.prepare(\"UPDATE jobs SET status='queued', attempts=MAX(attempts-1,0), progress_completed=0, run_after=0, updated_at=? WHERE id=? AND status='running'\").run(nowIso(), row.id);
      activeId = undefined;
      return;
    }
    db.prepare(\"UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'\").run(i, nowIso(), row.id);
  }
  db.prepare(\"UPDATE jobs SET status='completed', result_output=?, error=NULL, progress_completed=steps, updated_at=? WHERE id=? AND status='running'\").run(row.input.toUpperCase(), nowIso(), row.id);
  activeId = undefined;
}

try {
  while ("'!stopping) {
    const now = nowIso();
    const row = db.prepare(`UPDATE jobs SET status='"'running', attempts=attempts+1, progress_completed=0, updated_at=?
